  // behavioural clock gates for simulation of this file as is (sw/gen_variant.py replaces them by 97 + H
  // sky130_fd_sc_hd__dlclkp_1 instances at module level so that the netlist has no dotted instance names)
  reg [96:0]  row_we_l;
  reg [H-1:0] w2_we_l;
  always @* if (!wr_clk) begin row_we_l = row_we_q1; w2_we_l = w2_we_q1; end
  assign row_gclk = {97{wr_clk}} & row_we_l;
  assign w2_gclk  = {H{wr_clk}} & w2_we_l;
